package ai.lmctl.lmaws;

import com.sun.net.httpserver.HttpServer;
import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;

/** SDK loopback transport for SQS event-source mapping and DLQ requests. */
public final class QueueWorkerTransportChecks {
  public static void main(String[] args)throws Exception {
    int port=Integer.parseInt(System.getenv("LMAWS_TEST_PORT")); String account="000000000000",run="cafe07";
    String fn="arn:aws:lambda:us-east-1:"+account+":function:lmaws_cafe07_worker",queue="arn:aws:sqs:us-east-1:"+account+":lmaws_cafe07_source",dlq="arn:aws:sqs:us-east-1:"+account+":lmaws_cafe07_dlq",mapping="arn:aws:lambda:us-east-1:"+account+":event-source-mapping:12345678-1234-1234-1234-123456789012",foreignMapping="arn:aws:lambda:us-east-1:"+account+":event-source-mapping:22345678-1234-1234-1234-123456789012",untaggedMapping="arn:aws:lambda:us-east-1:"+account+":event-source-mapping:32345678-1234-1234-1234-123456789012";
    var reqs=Collections.synchronizedList(new ArrayList<String>()); var deleted=new AtomicInteger(); var mappingPolls=new AtomicInteger();
    var server=HttpServer.create(new InetSocketAddress("127.0.0.1",port),0); server.createContext("/",e->{String body=new String(e.getRequestBody().readAllBytes(),StandardCharsets.UTF_8),target=e.getRequestHeaders().getFirst("X-Amz-Target");String path=e.getRequestURI().getPath();reqs.add(path+" "+body);String out="{}",type="application/json";int status=200;
      if(body.contains("Action=GetCallerIdentity")){type="text/xml";out="<GetCallerIdentityResponse xmlns=\"https://sts.amazonaws.com/doc/2011-06-15/\"><GetCallerIdentityResult><Account>"+account+"</Account><Arn>arn:aws:sts::"+account+":user/fixture</Arn><UserId>x</UserId></GetCallerIdentityResult></GetCallerIdentityResponse>";}
      else if(body.contains("QueueName")){out="{\"QueueUrl\":\"https://sqs.us-east-1.amazonaws.com/000000000000/lmaws_cafe07_source\"}";}
      else if(body.contains("AttributeNames")){out="{\"Attributes\":{\"QueueArn\":\""+(body.contains("_dlq")?dlq:queue)+"\"}}";}
      else if(body.contains("QueueUrl")){out="{\"Tags\":{\"lmaws_test\":\""+run+"\"}}";}
      else if(body.contains("Action=SetQueueAttributes")){type="text/xml";out="<SetQueueAttributesResponse xmlns=\"http://queue.amazonaws.com/doc/2012-11-05/\"><ResponseMetadata><RequestId>x</RequestId></ResponseMetadata></SetQueueAttributesResponse>";}
      else if(path.contains("/tags/")&&path.contains("22345678")){out="{\"Tags\":{\"lmaws_test\":\"other-run\"}}";}
      else if(path.contains("/tags/")&&path.contains("32345678")){out="{\"Tags\":{}}";}
      else if(path.contains("/tags/")){out="{\"Tags\":{\"lmaws_test\":\""+run+"\"}}";}
      else if(path.contains("/functions/")&&e.getRequestMethod().equals("GET")){out="{\"Configuration\":{\"FunctionArn\":\""+fn+"\",\"State\":\"Active\"},\"Tags\":{\"lmaws_test\":\""+run+"\"}}";}
      else if(path.endsWith("/event-source-mappings")&&e.getRequestMethod().equals("GET")){out="{\"EventSourceMappings\":[{\"EventSourceMappingArn\":\""+mapping+"\",\"EventSourceArn\":\""+queue+"\",\"FunctionArn\":\""+fn+"\",\"State\":\"Enabled\"},{\"EventSourceMappingArn\":\""+foreignMapping+"\",\"EventSourceArn\":\""+queue+"\",\"FunctionArn\":\""+fn+"\",\"State\":\"Enabled\"},{\"EventSourceMappingArn\":\""+untaggedMapping+"\",\"EventSourceArn\":\""+queue+"\",\"FunctionArn\":\""+fn+"\",\"State\":\"Enabled\"}]}";}
      else if(path.endsWith("/event-source-mappings")&&e.getRequestMethod().equals("POST")){out="{\"EventSourceMappingArn\":\""+mapping+"\",\"EventSourceArn\":\""+queue+"\",\"FunctionArn\":\""+fn+"\",\"State\":\"Enabled\"}";}
      else if(path.contains("/event-source-mappings/")&&e.getRequestMethod().equals("GET")){if(deleted.get()>0){status=404;e.getResponseHeaders().add("x-amzn-ErrorType","ResourceNotFoundException");out="{\"message\":\"missing\"}";}else if(path.contains("22345678"))out="{\"EventSourceMappingArn\":\""+foreignMapping+"\",\"EventSourceArn\":\""+queue+"\",\"FunctionArn\":\""+fn+"\",\"State\":\"Enabled\"}";else if(path.contains("32345678"))out="{\"EventSourceMappingArn\":\""+untaggedMapping+"\",\"EventSourceArn\":\""+queue+"\",\"FunctionArn\":\""+fn+"\",\"State\":\"Enabled\"}";else {String state=mappingPolls.incrementAndGet()<2?"Creating":"Enabled";out="{\"EventSourceMappingArn\":\""+mapping+"\",\"EventSourceArn\":\""+queue+"\",\"FunctionArn\":\""+fn+"\",\"State\":\""+state+"\"}";}}
      else if(path.contains("/event-source-mappings/")&&e.getRequestMethod().equals("DELETE")){deleted.incrementAndGet();status=204;out="";}
      e.getResponseHeaders().add("Content-Type",type);byte[] b=out.getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(status,status==204?-1:b.length);if(b.length>0)e.getResponseBody().write(b);e.close();});server.start();
    try(var backend=new AwsBackend("us-east-1",false)){try{var worker=backend.createEventSourceMapping("https://sqs.us-east-1.amazonaws.com/"+account+"/lmaws_cafe07_source",fn,10,run);backend.waitEventSourceMappingEnabled(mapping,run,120);if(!"Enabled".equals(worker.status().get("state")))throw new AssertionError("mapping state");var inventory=backend.findEventSourceMappings(run);if(inventory.size()!=3||inventory.stream().filter(x->"false".equals(x.get("owned"))).count()!=2)throw new AssertionError("inventory omitted foreign/untagged mappings: "+inventory);try{backend.deleteEventSourceMapping(foreignMapping,run);throw new AssertionError("foreign mapping deletion accepted");}catch(SecurityException expected){}try{backend.deleteEventSourceMapping(untaggedMapping,run);throw new AssertionError("untagged mapping deletion accepted");}catch(SecurityException expected){}worker.delete();if(deleted.get()!=1)throw new AssertionError("mapping delete");backend.setSqsRedrive("https://sqs.us-east-1.amazonaws.com/"+account+"/lmaws_cafe07_source","https://sqs.us-east-1.amazonaws.com/"+account+"/lmaws_cafe07_dlq",run);backend.clearSqsRedrive("https://sqs.us-east-1.amazonaws.com/"+account+"/lmaws_cafe07_source",run);String captures=String.join("\n",reqs);if(!captures.contains("\\\"deadLetterTargetArn\\\":\\\""+dlq+"\\\"")||captures.contains("************"))throw new AssertionError("redrive request lost its actual DLQ ARN");if(!captures.contains("\"RedrivePolicy\":\"\""))throw new AssertionError("redrive clearing must send an empty string");System.out.println("PASS SQS mapping inventory, ownership guards and redrive SDK loopback requests");}catch(Throwable t){System.err.println(reqs);throw t;}}finally{server.stop(0);}
  }
}
